package dev.infend.skyrimtext;
/** Newly authored dialogue, not extracted original game quotations. */
final class FactionDialogue {
    private static final String[][][] LINES={{{"Кодлак Белая Грива","Мы узнаём друг друга не по обещаниям, а по поступкам. Вилкас покажет, чего требует наша служба.","Вилкас","Держи клинок уверенно, но не пытайся превратить упражнение в настоящую схватку."},
{"Фаркас","Обломок Вутрада остался в кургане. Мы идём вместе, и я рассчитываю, что ты не бросишь товарища.","Фаркас","Теперь ты видел то, что обычно остаётся за дверями Йоррваскра. Сохрани это между нами."},
{"Эйла","Ты заслужил право узнать тайну Круга. Решение принять нашу кровь должно быть твоим.","Скьор","Охотники Серебряной руки ждут за стенами. Не принимай их за обычных разбойников."},
{"Кодлак Белая Грива","Я устал от мысли, что после смерти моя душа не найдёт дороги в Совнгард. Поищи ведьм, связанных с нашим проклятием.","Кодлак Белая Грива","Мне нужна надежда на исцеление, а не ещё одна история о славном убийстве."},
{"Вилкас","Кодлак погиб, а части Вутрада украдены. Мы вернём то, что принадлежит Соратникам.","Вилкас","Гнев не должен заслонять цель. Найди обломки, даже если придётся отступить."},
{"Эйла","В гробнице Исграмора мы отдадим последнюю честь Кодлаку. От его судьбы зависит и судьба Круга.","Вилкас","Когда придёт время, помоги его духу избавиться от зверя. Тогда наш долг будет исполнен."}},
{{"Фаральда","Коллегия открывает двери тем, кто способен осознанно пользоваться магией. Покажи, чему ты научился.","Толфдир","Чары защищают не хуже стали, если понимаешь их природу. Начнём с защиты."},
{"Толфдир","Саартал хранит свидетельства первых нордских поселений. Следи за знаками и не касайся незнакомых артефактов бездумно.","Толфдир","Эта сфера не похожа на находки, которые мы ожидали. Нам понадобится помощь Коллегии."},
{"Ураг гро-Шуб","Из Арканеума унесли книги. Мне нужны сами тома, а не пересказ их содержания.","Ураг гро-Шуб","Вернёшь их целыми — сможем разобраться, что известно об Оке."},
{"Толфдир","Под Коллегией есть место, куда редко спускаются ученики. Найди Авгура и выслушай его.","Авгур Данлейнский","Вопрос не в том, кто владеет Оком. Вопрос в том, кто способен пережить его пробуждение."},
{"Мирабелла Эрвин","Исследователи Синода искали мощные магические предметы в Мзулфте. Их записи могут указать нам путь.","Мирабелла Эрвин","Если механизм ещё действует, используй его сведения, а не пытайся унести всю машину."},
{"Толфдир","Городу угрожает сила Ока. Сначала обезопась жителей; спорить с Анкано будем потом.","Толфдир","Нам нужно выиграть время. Не позволяй аномалиям прорваться к домам."},
{"Мирабелла Эрвин","Лабиринтиан помнит ошибки прежних магов. Найди Посох Магнуса и возвращайся.","Морокеи","Ты приближаешься к силе, которой не понимаешь. Докажи, что способен противостоять ей."},
{"Толфдир","Посох — наш шанс ослабить Око. Пока Анкано черпает из него силу, обычная атака бесполезна.","Анкано","Ты называешь это опасностью, потому что не можешь владеть тем, что досталось мне."}},
{{"Бриньольф","Рынок полон внимательных глаз. Мне нужен человек, который умеет действовать, не привлекая лишнего внимания.","Бриньольф","Если дело пойдёт не так, не устраивай драку на площади. У гильдии есть другие способы оценить тебя."},
{"Бриньольф","Торговцы задолжали гильдии. Выясни, чем можно убедить каждого, прежде чем выбирать способ.","Бриньольф","Город тесен, и дурная слава разносится быстро. Вернись с результатом, а не с толпой стражников."},
{"Мерсер Фрей","Золотое поместье перестало соблюдать договорённости. Меня интересуют документы и то, кто за ними стоит.","Бриньольф","Помни: это проверка твоей аккуратности. Не уничтожай всё, что окажется на пути."},
{"Мавен Чёрный Вереск","Медоварня Хоннинга стала помехой моим делам. Тебе предстоит разобраться с её производством.","Мавен Чёрный Вереск","Действуй так, чтобы последствия не привели к моей двери."},
{"Бриньольф","Гулум-Ай связан с той странной сделкой. Найди его в Солитьюде и выясни, что он скрывает.","Гулум-Ай","Не всякая торговля проходит на глазах у таможенников. Зачем тебе знать о моих покупателях?"},
{"Мерсер Фрей","В Снежной Завесе нас ждёт человек, которого я давно разыскиваю. Не отставай.","Карлия","Остановись и выслушай меня. Тот, кому ты доверял, не рассказал тебе всей истории."},
{"Карлия","Дневник Галла хранит доказательства, но написан так, что мы не можем его прочитать.","Энтир","Мне понадобится образец двемерского письма. Принеси сведения, которые помогут сопоставить символы."},
{"Бриньольф","Если Карлия говорит правду, Мерсер лишил нас куда большего, чем золото. Найди его планы.","Карлия","В доме Мерсера должны остаться следы его следующей цели. Не пропусти их."},
{"Карлия","Ноктюрнал требует не слов, а обязательства. Если примешь договор, он изменит твою связь с гильдией.","Бриньольф","Мы должны остановить Мерсера. Но сначала реши, готов ли стать Соловьём."},
{"Карлия","Мерсер ушёл в Иркнтанд за сокровищем. Вернём ключ и положим конец его предательству.","Мерсер Фрей","Ты слишком поздно понял, как устроена эта гильдия. Посмотрим, кому достанется добыча."},
{"Карлия","Скелетный ключ не принадлежит смертным. Верни его в Сумеречную гробницу.","Ноктюрнал","Исполненный договор говорит больше, чем клятва. Оставь то, что мне принадлежит."}},
{{"Авентус Аретино","Я долго ждал ответа на свой призыв. Мне нужно, чтобы кто-то услышал мою просьбу.","Авентус Аретино","Я не знаю, кто ты, но надеюсь, что смогу снова почувствовать себя в безопасности."},
{"Астрид","Ты привлёк внимание Братства. Теперь реши, хочешь ли вступить в нашу организацию.","Астрид","Если согласишься, найди убежище. Там тебе объяснят, что означает контракт."},
{"Назир","Здесь у каждого есть обязанности. Я объясню, как устроены наши поручения и где искать заказчиков.","Астрид","Не забывай, что убежище должно оставаться тайной."},
{"Муири","Мне нужен тот, кто выполнит принятое поручение. У этой истории есть прошлое, о котором я не люблю говорить.","Назир","Отнесись к условиям контракта внимательно. Вернись, когда решение принято."},
{"Мать Ночи","Прислушайся не к шуму вокруг, а к тому, что скрывается за ним. У меня есть поручение.","Астрид","Слова Матери Ночи меняют привычный порядок. Нам придётся решить, как жить с этим дальше."},
{"Амонд Мотьер","Мой заказ касается дела, которое может изменить Империю. Здесь важны тайна и последовательность.","Амонд Мотьер","Ты получишь сведения о следующем этапе. Не доверяй тем, кто слишком охотно предлагает помощь."},
{"Астрид","На свадьбе в Солитьюде решается не только судьба двух семей. Это часть поручения Братства.","Астрид","Когда вернёшься, сообщи о результате и не привлекай внимание к убежищу."},
{"Астрид","Пенитус Окулатус усиливает охрану императора. Наше поручение связано с этим препятствием.","Назир","Заверши контракт и не позволяй его последствиям раскрыть наши планы."},
{"Астрид","Цицерон покинул убежище. Найди его и реши, что делать с предательством.","Цицерон","Ты пришёл за мной? Тогда выслушай хотя бы то, почему я оказался здесь."},
{"Фестус Крекс","Чтобы продолжить, нужно выяснить, кто скрывается за именем Гурмана. Ищи подтверждения, а не слухи.","Назир","Личность Гурмана должна быть установлена прежде, чем Братство перейдёт к следующему шагу."},
{"Астрид","Настал момент, к которому мы готовились. Но слишком многое зависит от того, кому можно верить.","Командир Марон","Ваш замысел раскрыт. Теперь посмотрим, сумеешь ли ты покинуть Солитьюд."},
{"Назир","Убежище атаковано! Выбирайся и помоги тем, кто ещё жив.","Астрид","Я допустила ошибку. Судьба Братства теперь зависит от того, что ты решишь дальше."},
{"Амонд Мотьер","Последний этап поручения ещё не завершён. Император находится на корабле.","Мать Ночи","Когда завершится контракт, Братство должно найти силы жить дальше."}},
{{"Легат Рикке","Легиону нужны солдаты, а не только желающие носить форму. Очисти форт Храгстад.","Легат Рикке","Если справишься, получишь право служить. Дисциплина будет важна на каждом следующем задании."},
{"Легат Рикке","Зубчатая корона нужна не ради золота. Её символ имеет значение для всей войны.","Легат Рикке","В Корваньюнде опасно. Забери корону и не дай противнику опередить нас."},
{"Генерал Туллий","Вайтран должен получить наше послание прежде, чем армия восставших подойдёт к городу.","Ярл Балгруф","Мне предстоит выбрать, кто сможет защитить моих людей. Передай Туллию мой ответ."},
{"Легат Рикке","Ворота Вайтрана под угрозой. Держи позицию и не позволяй противнику пройти к городу.","Ярл Балгруф","Сегодня мы защищаем дома, а не чужие знамена."},
{"Генерал Туллий","После Вайтрана война не окончена. Нам предстоит вернуть контроль над владениями.","Легат Рикке","Сначала нужны сведения о дорогах и укреплениях, затем начнётся наступление."},
{"Легат Рикке","Данстад прикрывает важный участок дороги. Возьмём форт и удержим его.","Легат Рикке","Не преследуй противника далеко от позиции. Нам нужна крепость."},
{"Легат Рикке","Нужно добиться поддержки в Рифтене. Без местных сведений наши планы останутся на бумаге.","Ярл Рифтена","У моего города свои заботы. Объясни, почему я должен доверять вашему предложению."},
{"Легат Рикке","Форт Амол стоит на пути к Виндхельму. Захвати позицию и обеспечь подход основным силам.","Генерал Туллий","После этого путь к столице восстания станет открыт."},
{"Генерал Туллий","Последняя битва ждёт в Виндхельме. Не теряй строй и помни, ради чего мы сюда пришли.","Легат Рикке","Когда сопротивление закончится, город должен вернуться к мирной жизни."}},
{{"Галмар Каменный Кулак","Одних слов о свободе мало. Докажи, что можешь пережить испытание на севере.","Галмар Каменный Кулак","Если вернёшься, поговорим о службе Ульфрику."},
{"Галмар Каменный Кулак","Корона древних королей должна достаться нам. Имперцы ищут её в тех же руинах.","Галмар Каменный Кулак","Верни её, прежде чем чужие руки вынесут находку из Корваньюнда."},
{"Ульфрик Буревестник","Передай ярлу Вайтрана моё послание. Он должен сам решить, какой путь выберет.","Ярл Балгруф","Война может уничтожить то, что я защищал всю жизнь. Я не приму решение легкомысленно."},
{"Галмар Каменный Кулак","Мы выступаем к Вайтрану. Наш отряд должен пробиться через оборону.","Галмар Каменный Кулак","Не забывай о товарищах, даже когда ворота окажутся открыты."},
{"Галмар Каменный Кулак","В Нойграде удерживают наших людей. Освободи их и помоги отряду взять укрепление.","Галмар Каменный Кулак","Свободные пленники важнее трофеев. Убедись, что они могут уйти."},
{"Галмар Каменный Кулак","Маркарта нельзя добиться одним натиском. Понадобятся сведения и договорённости.","Представитель ярла","Я выслушаю предложение, но сначала объясни, чего требует ваша сторона."},
{"Галмар Каменный Кулак","Сноухок мешает продвигаться через Хьялмарк. Отряд должен взять его.","Галмар Каменный Кулак","Удержите позицию до прибытия подкрепления."},
{"Галмар Каменный Кулак","Храгстад — последний серьёзный рубеж на пути к Солитьюду. Начинаем наступление.","Ульфрик Буревестник","Если крепость падёт, мы сможем идти к столице."},
{"Ульфрик Буревестник","Сегодня решается судьба нашей войны. Вступай в Солитьюд вместе с отрядом.","Галмар Каменный Кулак","Когда бой закончится, у нас начнётся другой труд: восстановить Скайрим."}},
{{"Изран","Вампиры становятся смелее. Стража Рассвета снова нужна Скайриму, и нам необходимы союзники.","Изран","Отправляйся на разведку. Не считай любую ночную тень доказательством угрозы."},
{"Изран","В Димхоллоу произошло нечто необычное. Выясни, что вампиры там искали.","Серана","Ты не из тех, кого я ожидала увидеть. Помоги мне выбраться, и я объясню, куда нужно идти."},
{"Серана","Мой отец ждёт в Волкихаре. Мне нужно вернуться домой, хотя я не знаю, что там изменилось.","Харкон","Ты помог моей дочери. Перед тобой выбор, который определит, кто ты для моего дома."},
{"Изран","Нам нужны люди, которые умеют сражаться с вампирами. Найди Сорин и Гунмара.","Изран","Когда они согласятся, мы сможем подготовить форт к настоящей войне."},
{"Серана","Чтобы прочесть свиток, нужен жрец Мотылька. Следы ведут к дороге у моста.","Изран","Выведи жреца из-под власти вампиров. Он нужен нам живым."},
{"Серана","Для понимания пророчества одного свитка недостаточно. Поищем другой след в северных руинах.","Серана","Если найдём нужный свиток, не пытайся читать его без подготовки."},
{"Серана","Моя мать скрывала исследования от отца. В замке должны остаться следы её лаборатории.","Серана","Будь осторожен: путь, который мы ищем, может вести за пределы нашего мира."},
{"Валерика","Ты привёл мою дочь в место, откуда нелегко вернуться. Сначала придётся справиться с хранителями.","Серана","Помоги нам разобраться с преградой. Мы ещё не закончили."},
{"Серана","Без понимания пророчества мы не узнаем, где искать лук. Нужно подготовиться к чтению свитков.","Серана","Я буду рядом. Не торопись: это знание может иметь цену."},
{"Гелебор","Путь к луку проходит через святилища моего народа. Помоги мне остановить того, кто осквернил их.","Виртур","Ты пришёл ради лука? Тогда узнай, какой ценой была рождена эта история."},
{"Изран","Мы дошли до конца пути. Харкон не должен исполнить пророчество.","Серана","Я знаю, что предстоит встретиться с отцом. Но на этот раз решение будет нашим."}}};
    static int count(int f){return LINES[f].length;}
    static String scene(int f,int chapter){String[] line=LINES[f][chapter];return "**"+line[0]+":**\n>**— "+line[1]+"**\n\n**"+line[2]+":**\n>**— "+line[3]+"**";}
}
